<template><section class="page workbench"><div class="page-title"><div><h1>实时作业工作台</h1><p class="muted">摄像头、算法检测与作业状态</p></div><button class="ghost" @click="history=true">历史记录</button></div><div class="work-grid"><div><div class="video-card"><div class="video-stage"><video ref="video" autoplay muted playsinline></video><span class="fps">FPS {{status.fps?.toFixed?.(1)||'--'}}</span><span class="stream-tag">{{status.algorithm==='running'?'算法结果':'原始视频'}}</span></div><div class="actions"><button @click="camera('start')" :disabled="status.camera==='running'">启动摄像头</button><button @click="camera('stop')" :disabled="status.camera!=='running'">关闭摄像头</button><button @click="algorithm('start')" :disabled="status.camera!=='running'||status.algorithm==='running'">启动算法</button><button @click="algorithm('stop')" :disabled="status.algorithm!=='running'">关闭算法</button><button class="record" @click="recording">{{recordingOn?'停止录制':'开始录制'}}</button></div></div><div class="metric-row"><Metric label="FPS" :value="status.fps" unit="FPS"/><Metric label="NPU 延迟" :value="status.npu_latency_ms" unit="ms"/><Metric label="CPU 温度" :value="status.cpu_temperature_c" unit="°C"/></div></div><aside class="job-card"><h2>当前 SOP 步骤</h2><div class="step-current">安装连接器</div><p>将连接器正确插入主板对应接口并确保卡扣到位</p><div class="progress"><i style="width:37%"></i></div><strong>整体进度　37%</strong><div class="landmark">手部关键点（21点） <label class="switch"><input type="checkbox" v-model="landmarks" @change="toggleLandmarks"><i></i></label></div><p class="muted">关键点可视化{{landmarks?'已启用':'已关闭'}}</p></aside></div><div v-if="message" class="toast">{{message}}</div><div v-if="history" class="modal"><div class="modal-card"><div class="page-title"><h2>录像列表</h2><button class="ghost" @click="history=false">关闭</button></div><p v-if="!videos.length" class="muted">暂无已保存录像</p><div v-for="v in videos" :key="v.filename" class="video-item"><span>{{v.filename}}<small>{{v.size_mb}} MB · {{new Date(v.modified_at*1000).toLocaleString()}}</small></span><button @click="download(v.filename)">下载</button><button class="danger" @click="remove(v.filename)">删除</button></div></div></div></section></template><script setup>import {ref,onMounted,onUnmounted} from 'vue';import {api,post,request} from '../api';import Metric from '../components/Metric.vue';const video=ref(),status=ref({}),landmarks=ref(true),recordingOn=ref(false),history=ref(false),videos=ref([]),message=ref('');let timer;const notify=t=>{message.value=t;setTimeout(()=>message.value='',2500)};async function sync(){try{status.value=await request('/api/algorithm/status')}catch(e){}}async function camera(a){try{status.value=await post('/api/camera/'+a,{resolution:'640x480'});notify(a==='start'?'摄像头已启动':'摄像头已关闭')}catch(e){notify(e.message)}}async function algorithm(a){try{status.value=await post('/api/algorithm/'+a,{resolution:'640x480'});notify(a==='start'?'算法已启动':'算法已关闭')}catch(e){notify(e.message)}}async function toggleLandmarks(){try{await post('/api/visualization/hand-landmarks',{enabled:landmarks.value})}catch(e){notify(e.message)}}async function recording(){try{const p=await post('/api/recording/'+(recordingOn.value?'stop':'start'),{mode:'processed'});recordingOn.value=!recordingOn.value;status.value=p;notify(recordingOn.value?'已开始录制':'录像已保存')}catch(e){notify(e.message)}}async function loadVideos(){videos.value=(await request('/api/recordings')).items||[]}function download(f){const a=document.createElement('a');a.href=api+'/api/recordings/'+encodeURIComponent(f)+'/download';a.download=f;a.click()}async function remove(f){if(!confirm('确认删除 '+f+'？'))return;await fetch(api+'/api/recordings/'+encodeURIComponent(f),{method:'DELETE'});loadVideos()}onMounted(()=>{sync();timer=setInterval(sync,1000);loadVideos()});onUnmounted(()=>clearInterval(timer));</script>
<script>let vuePeer=null,vuePath='';async function vueConnect(){const v=document.querySelector('.video-stage video');if(!v)return;try{const apiBase=(new URLSearchParams(location.search).get('api')||location.origin).replace(/\/$/,'');const s=await (await fetch(apiBase+'/api/algorithm/status')).json();const ready=s.algorithm==='running'?s.stream_ready:s.raw_stream_ready;if(s.camera!=='running'||!ready)return;const path=s.algorithm==='running'?'sop':'raw';if(vuePath===path&&vuePeer)return;if(vuePeer)vuePeer.close();vuePeer=new RTCPeerConnection();vuePeer.ontrack=e=>{if(e.streams[0]){v.srcObject=e.streams[0];v.play().catch(()=>{})}};vuePeer.addTransceiver('video',{direction:'recvonly'});await vuePeer.setLocalDescription(await vuePeer.createOffer());await new Promise(r=>{if(vuePeer.iceGatheringState==='complete')r();else vuePeer.onicegatheringstatechange=()=>vuePeer.iceGatheringState==='complete'&&r()});const r=await fetch(`${location.protocol}//${location.hostname}:8889/${path}/whep`,{method:'POST',headers:{'Content-Type':'application/sdp'},body:vuePeer.localDescription.sdp});if(r.ok){await vuePeer.setRemoteDescription({type:'answer',sdp:await r.text()});vuePath=path}}catch(e){}}setInterval(vueConnect,1000);window.addEventListener('beforeunload',()=>vuePeer&&vuePeer.close());</script>
<!-- Background assets: generated industrial scene plus the previous workbench reference. -->
